const s3=wb.getWorksheet('Sheet3');
const vals=wb.getRange('Sheet3!A1:D300').getValues();
const names=wb.getRange('Sheet1!F2:F7').getValues().map(r=>String(r[0]));
const out:any[]=[];
for(const n of names){
 const key=n.replace(/[^a-z0-9]/gi,'').toLowerCase();
 vals.forEach((r,i)=>{const t=String(r[0]??''); if(t.replace(/[^a-z0-9]/gi,'').toLowerCase()===key) out.push({n:JSON.stringify(n),row:i+1,t:JSON.stringify(t),codes:[...t].slice(0,3).map(c=>c.charCodeAt(0)),tail:[...t].slice(-2).map(c=>c.charCodeAt(0)),b:r[1],c:r[2],d:r[3]});});
}
log(JSON.stringify(out,null,0));
log(JSON.stringify(names.map(n=>[...n].filter(c=>c.charCodeAt(0)>126||c===' ').map(c=>c.charCodeAt(0)))));
log(JSON.stringify(vals.slice(0,8)));
log(JSON.stringify(vals.slice(-3)));
const nonstr=vals.slice(1).map((r,i)=>[i+2,r[0]]).filter(x=>typeof x[1]!=='string');log(JSON.stringify(nonstr.slice(0,20)));
const notLead=vals.slice(1).filter(r=>typeof r[0]==='string'&&!/^\s/.test(r[0])).length;log('noLeadingSpace',notLead, 'trailing', vals.slice(1).filter(r=>typeof r[0]==='string'&&/\s$/.test(r[0])).length);
