log(wb.getRange('Sheet1!G2').getCell ? JSON.stringify(wb.getRange('Sheet1!G1:I2').getValues()):'')

const f=[];for(let r=2;r<=7;r++){f.push([2,3,4].map(c=>`=VLOOKUP(F${r},TRIM(Sheet3!$A$2:$D$300),${c},FALSE)`));}
const rg=wb.getRange('Sheet1!G2:I7');
rg.setFormulas(f);
const st=rg.getStyle();
st.setNumberFormat('@');
st.setAlignment({horizontal:'left'});
const out=[];
for(const a of ['G2','H2','I2','G7','H7','I7']){const c=wb.getRange('Sheet1!'+a).getCell();out.push([a,c.getFormula?.(),typeof c.getValue(),c.getValue(),c.getText?.()]);}
log(JSON.stringify(out));
